import { API_BASE_URL } from '../utils/appEnv';

/**
 * agentApi — platform catalog of the LoanAgents_SmartLoans agents (dbo.agents,
 * one list for every company). Generated by posgmo-factory (PRD prd_agent.json)
 * and fixed by hand.
 *   POST /all_agents   sp_agents_all  — any staff session
 *   POST /one_agents   sp_agents_one  — any staff session
 *   POST /agents       sp_agents      — 1 insert · 2 update · 3 retire; SmartLoans admin only
 * The agent's prompt, model and tools live in code; this is only its card.
 */
const LOG = '[agentApi]';

export type AgentArea = 'whatsapp' | 'pos_support' | 'loans' | 'extraction' | 'other';
export type AgentStatus = 'activo' | 'retirado';

export interface Agent {
  agentId: number;
  agentKey: string;
  name: string;
  description: string;
  area: AgentArea;
  /** Route path only (e.g. /support/whatsapp-reservations), never the host. */
  endpoint: string;
  /** Informational: changing it here changes nothing in the agent. */
  model: string;
  customerFacing: boolean;
  status: AgentStatus;
  createdAt: string;
  updatedAt: string;
}

export type AgentInput = Pick<Agent, 'agentKey' | 'name' | 'description' | 'area' | 'endpoint' | 'model' | 'customerFacing'>;

export interface AgentFilters {
  area?: AgentArea;
  status?: AgentStatus;
  search?: string;
}

interface AgentRow extends Omit<Agent, 'customerFacing' | 'createdAt' | 'updatedAt'> {
  customerFacing: number | boolean;
  created_At?: string;
  updated_at?: string;
}

const toAgent = (r: AgentRow): Agent => ({
  ...r,
  customerFacing: r.customerFacing === true || Number(r.customerFacing) === 1,
  createdAt: r.created_At ?? '',
  updatedAt: r.updated_at ?? '',
});

async function post<T>(path: string, body: unknown): Promise<T> {
  const res = await fetch(`${API_BASE_URL}${path}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok || data?.error || data?.status === 'error') {
    const message = data?.message || data?.error || data?.detail || `HTTP ${res.status}`;
    console.error(LOG, path, message);
    throw new Error(typeof message === 'string' ? message : 'Error');
  }
  return data as T;
}

export async function getAllAgents(filters: AgentFilters = {}): Promise<Agent[]> {
  const data = await post<{ agents?: AgentRow[] }>('/all_agents', { agents: [filters] });
  return (data.agents ?? []).map(toAgent);
}

export async function createAgent(input: AgentInput): Promise<void> {
  await post('/agents', { agents: [{ action: 1, ...input, customerFacing: input.customerFacing ? 1 : 0 }] });
}

export async function updateAgent(agentId: number, input: Omit<AgentInput, 'agentKey'>): Promise<void> {
  await post('/agents', { agents: [{ action: 2, agentId, ...input, customerFacing: input.customerFacing ? 1 : 0 }] });
}

export async function retireAgent(agentId: number): Promise<void> {
  await post('/agents', { agents: [{ action: 3, agentId }] });
}
